                for j in range(i + 1, len(g_vals)):
                    for l in range(j + 1, len(g_vals)):
                        for m in range(l + 1, len(g_vals)):
                            a1, a2, a3, a4 = i - a_range, j - a_range, l - a_range, m - a_range
                            target = g_vals[i] + g_vals[j] + g_vals[l] + g_vals[m]
                            if target in val_to_x:
                                for a5 in val_to_x[target]:
                                    if a5 not in (a1, a2, a3, a4):
                                        return True, k
    return False, None

