def check_g_exists_k_fast_v2(n, d, coeffs, a_range):
    from collections import defaultdict
    def g(x):
        val = x**d
        for i, c in enumerate(coeffs):
            val += c * (x**(d - 1 - i))
        return val

    g_vals = []
    val_to_x = defaultdict(list)
    for x in range(-a_range, a_range + 1):
        v = g(x)
        g_vals.append(v)
        val_to_x[v].append(x)

    for k in range(1, n + 1):
        if k == 1:
            for v in val_to_x:
                if len(val_to_x[v]) >= 2:
                    return True, k
        elif k == 2:
            for i in range(len(g_vals)):
                for j in range(i + 1, len(g_vals)):
                    a1, a2 = i - a_range, j - a_range
                    target = g_vals[i] + g_vals[j]
                    if target in val_to_x:
                        for a3 in val_to_x[target]:
                            if a3 != a1 and a3 != a2:
                                return True, k
        elif k == 3:
            # k=3: g(a4) = g(a1) + g(a2) + g(a3)
            # Use sum2 to speed up
            sum2 = defaultdict(list)
            for i in range(len(g_vals)):
                for j in range(i + 1, len(g_vals)):
                    a1, a2 = i - a_range, j - a_range
                    sum2[g_vals[i] + g_vals[j]].append((a1, a2))

            for i in range(len(g_vals)):
                for j in range(i + 1, len(g_vals)):
                    for l in range(j + 1, len(g_vals)):
                        a1, a2, a3 = i - a_range, j - a_range, l - a_range
                        target = g_vals[i] + g_vals[j] + g_vals[l]
                        if target in val_to_x:
                            for a4 in val_to_x[target]:
                                if a4 != a1 and a4 != a2 and a4 != a3:
                                    return True, k
    return False, None

print(check_g_exists_k_fast_v2(3, 3, [-6, -10, 5], 100))
